import{V as e,et as t,mt as n,tt as r}from"./chunks/framework.DPTLmtS5.js";var i=JSON.parse(`{"title":"Choix de confidentialité","description":"","frontmatter":{},"headers":[],"relativePath":"fr/guide/privacy-choices.md","filePath":"fr/guide/privacy-choices.md","lastUpdated":1793173149000}`),a={name:`fr/guide/privacy-choices.md`};function o(e,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[r(`<h1 id="choix-de-confidentialite" tabindex="-1">Choix de confidentialité <a class="header-anchor" href="#choix-de-confidentialite" aria-label="Permalink to “Choix de confidentialité”">​</a></h1><p>Sudoku est une application conçue hors ligne en priorité, avec des pratiques minimales en matière de données. Cette page présente vos options de confidentialité et la manière de contrôler vos données.</p><h2 id="vos-donnees-restent-sur-votre-appareil-par-defaut" tabindex="-1">Vos données restent sur votre appareil (par défaut) <a class="header-anchor" href="#vos-donnees-restent-sur-votre-appareil-par-defaut" aria-label="Permalink to “Vos données restent sur votre appareil (par défaut)”">​</a></h2><ul><li>Toutes les données de jeu — réglages, état de la partie, notes au crayon et statistiques — sont stockées localement sur votre appareil par défaut.</li><li>Le cœur du jeu ne nécessite aucun accès réseau.</li><li>Il n&#39;y a ni publicité, ni analyse d&#39;audience, ni suivi.</li></ul><h2 id="fonctions-cloud-facultatives" tabindex="-1">Fonctions cloud facultatives <a class="header-anchor" href="#fonctions-cloud-facultatives" aria-label="Permalink to “Fonctions cloud facultatives”">​</a></h2><h3 id="synchronisation-icloud" tabindex="-1">Synchronisation iCloud <a class="header-anchor" href="#synchronisation-icloud" aria-label="Permalink to “Synchronisation iCloud”">​</a></h3><p>Si vous choisissez d&#39;activer la synchronisation iCloud :</p><ul><li>Les données sont synchronisées uniquement vers <strong>votre compte iCloud personnel</strong> — jamais vers un serveur que nous contrôlons.</li><li>CloudKit d&#39;Apple assure le chiffrement en transit et au repos.</li><li>Vous pouvez la désactiver à tout moment : Réglages → [Votre nom] → iCloud → Apps utilisant iCloud → désactivez Sudoku.</li></ul><h3 id="game-center" tabindex="-1">Game Center <a class="header-anchor" href="#game-center" aria-label="Permalink to “Game Center”">​</a></h3><p>Si vous choisissez d&#39;utiliser Game Center :</p><ul><li>Les scores des classements peuvent apparaître publiquement sous votre nom d&#39;affichage Game Center.</li><li>La progression des succès est enregistrée par Game Center.</li><li>Vous pouvez la désactiver en vous déconnectant de Game Center dans les réglages.</li></ul><h2 id="la-seule-fonction-reseau-hors-cloud-«-plus-d-apps-»" tabindex="-1">La seule fonction réseau hors cloud : « Plus d&#39;apps » <a class="header-anchor" href="#la-seule-fonction-reseau-hors-cloud-«-plus-d-apps-»" aria-label="Permalink to “La seule fonction réseau hors cloud : « Plus d&#39;apps »”">​</a></h2><p>Le seul autre accès réseau est la section facultative <strong>« Plus d&#39;apps »</strong> dans les réglages, qui récupère une liste d&#39;applications de la même famille. Cette fonction :</p><ul><li>N&#39;envoie aucune donnée personnelle — elle récupère seulement une liste de noms et de liens d&#39;applications.</li><li>Peut être totalement ignorée, sans aucune incidence sur le jeu.</li><li>Ne vous suit pas et ne stocke aucun identifiant.</li></ul><h2 id="effacer-vos-donnees" tabindex="-1">Effacer vos données <a class="header-anchor" href="#effacer-vos-donnees" aria-label="Permalink to “Effacer vos données”">​</a></h2><p>Pour supprimer toutes les données de l&#39;application de votre appareil :</p><ul><li><strong>iPhone/iPad</strong> : supprimez puis réinstallez l&#39;application</li><li><strong>Mac</strong> : quittez Sudoku, puis supprimez le conteneur :</li></ul><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">rm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -rf</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/Library/Containers/com.w3cub.sudoku</span></span></code></pre></div><p>Pour effacer également les données synchronisées via iCloud :</p><ol><li>Ouvrez <strong>Réglages → [Votre nom] → iCloud → Gérer le stockage du compte</strong></li><li>Recherchez Sudoku dans la liste des applications</li><li>Touchez <strong>Supprimer les données</strong></li></ol><p>Cette opération supprime définitivement d&#39;iCloud tous les réglages, les statistiques, les parties sauvegardées et la progression du défi quotidien.</p><h2 id="aucun-suivi-aucune-publicite" tabindex="-1">Aucun suivi, aucune publicité <a class="header-anchor" href="#aucun-suivi-aucune-publicite" aria-label="Permalink to “Aucun suivi, aucune publicité”">​</a></h2><p>Sudoku ne contient ni publicité, ni analyse d&#39;audience, ni pixel de suivi, ni intégration de partage de données avec des tiers. L&#39;application ne nécessite aucun accès réseau pour jouer.</p><h2 id="recapitulatif-des-demandes-de-confidentialite" tabindex="-1">Récapitulatif des demandes de confidentialité <a class="header-anchor" href="#recapitulatif-des-demandes-de-confidentialite" aria-label="Permalink to “Récapitulatif des demandes de confidentialité”">​</a></h2><table tabindex="0"><thead><tr><th>Demande</th><th>Obligatoire ?</th><th>Ce qu&#39;elle fait</th></tr></thead><tbody><tr><td>Stockage local</td><td>Oui (automatique)</td><td>Stocke les données de jeu sur l&#39;appareil</td></tr><tr><td>Synchronisation iCloud</td><td>Facultative</td><td>Synchronise les données entre vos appareils via CloudKit</td></tr><tr><td>Game Center</td><td>Facultative</td><td>Classements et succès</td></tr><tr><td>Réseau (« Plus d&#39;apps »)</td><td>Facultative</td><td>Récupère la liste des applications de la même famille</td></tr></tbody></table><p>Étant donné qu&#39;aucune donnée personnelle n&#39;est collectée ni transmise à des serveurs que nous contrôlons, il n&#39;existe aucune base de données centrale à consulter, supprimer ou exporter. Toutes les données sont soit locales, soit gérées par les services d&#39;Apple (iCloud et Game Center).</p><h2 id="contact" tabindex="-1">Contact <a class="header-anchor" href="#contact" aria-label="Permalink to “Contact”">​</a></h2><p>Si vous avez des questions sur ce processus, ouvrez une issue à l&#39;adresse <code>https://github.com/sudoku-pro/sudoku-site/issues</code> ou écrivez à <a href="mailto:sudoku@w3cub.com" target="_blank" rel="noreferrer">sudoku@w3cub.com</a>.</p>`,28)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};